"""Generate the formatter reference pages: docs/formats/<module>.md for every module in
textkit.formats, from the module's docstring and a sample table rendered with it.

    python scripts/gen_format_docs.py [--out docs/formats]

Run it after adding or changing a formatter. Every generated page starts with GENERATED_MARK.
"""

from __future__ import annotations

import argparse
import importlib
import pkgutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

import textkit.formats  # noqa: E402

GENERATED_MARK = "<!-- generated by scripts/gen_format_docs.py"
HEADERS = ("sku", "name", "qty")
ROWS = [("W-1", "Widget", 3), ("G-2", "Gadget, large", None)]


def formatters() -> list[str]:
    return sorted(info.name for info in pkgutil.iter_modules(textkit.formats.__path__))


def page(name: str) -> str:
    module = importlib.import_module(f"textkit.formats.{name}")
    doc = (module.__doc__ or "").strip()
    sample = module.render(ROWS, HEADERS).rstrip("\n")
    return (
        f"{GENERATED_MARK} from textkit.formats.{name}; do not edit -->\n"
        f"# `{name}`\n\n{doc}\n\nUsage: `from textkit.formats.{name} import render`\n\n"
        f"Sample output:\n\n```\n{sample}\n```\n"
    )


def generate(out_dir: str | Path) -> list[Path]:
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    written = []
    for name in formatters():
        path = out / f"{name}.md"
        path.write_text(page(name), encoding="utf-8")
        written.append(path)
    return written


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="gen_format_docs.py")
    parser.add_argument("--out", default=str(ROOT / "docs" / "formats"))
    args = parser.parse_args(argv)
    for path in generate(args.out):
        print(path)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
